CREATE OR REPLACE VIEW CBSAX.ACCOUNT (ACCOUNT_EYECATCHER, ACCOUNT_CUSTOMER_NUMBER, ACCOUNT_SORTCODE, ACCOUNT_NUMBER, ACCOUNT_TYPE, ACCOUNT_INTEREST_RATE, ACCOUNT_OPENED, ACCOUNT_OVERDRAFT_LIMIT, ACCOUNT_LAST_STATEMENT, ACCOUNT_NEXT_STATEMENT, ACCOUNT_AVAILABLE_BALANCE, ACCOUNT_ACTUAL_BALANCE) AS WITH N (I) AS (VALUES 1 UNION ALL SELECT I + 1 FROM N WHERE I < 10000001) SELECT CAST('ACCT' AS CHAR(4)), CAST('0000000001' AS CHAR(10)), CAST('987654' AS CHAR(6)), CAST(RIGHT('00000000' || RTRIM(CHAR(I)), 8) AS CHAR(8)), CAST('CURRENT' AS CHAR(8)), CAST(0 AS DECIMAL(6, 2)), CAST('2019-03-15' AS DATE), 0, CAST(NULL AS DATE), CAST(NULL AS DATE), CAST(0 AS DECIMAL(12, 2)), CAST(0 AS DECIMAL(12, 2)) FROM N;
